mapper.select:
SELECT id, config_key, config_value::text AS config_value, config_name, is_status, remark, update_time
FROM sys_config
WHERE id = #{id}

SELECT id, config_key, config_value::text AS config_value, config_name, is_status, remark, update_time FROM sys_config
AND config_key LIKE CONCAT('%', #{configKey}, '%')
AND config_name LIKE CONCAT('%', #{configName}, '%')
AND is_status = #{isStatus}
ORDER BY update_time DESC, id DESC LIMIT #{limit} OFFSET #{offset}
